// FASE 1: Captura en tiempo real de acciones individuales
const action = $json.action || $json;
const sessionId = $json.sessionId || `session_${Date.now()}`;

// Validar que tenemos una acción válida
if (!action.type || !action.timestamp) {
  return [{
    json: {
      success: false,
      error: 'Invalid action data',
      received: $json
    }
  }];
}

// Preparar datos para almacenamiento
const actionData = {
  sessionId: sessionId,
  action: {
    ...action,
    capturedAt: new Date().toISOString(),
    url: $json.url || '',
    title: $json.title || ''
  },
  metadata: {
    userAgent: $json.userAgent || '',
    timestamp: Date.now()
  }
};

console.log('📝 Action captured for session:', sessionId, 'Action:', action.type);

return [{json: actionData}];

// ALMACENAMIENTO TEMPORAL EN MEMORIA (para n8n 1.114.4)
// En una implementación real, esto se enviaría a una base de datos
const actionData = $json;
const sessionId = actionData.sessionId;

// Simular almacenamiento exitoso
console.log(`📝 [STORAGE] Action stored for session ${sessionId}:`, actionData.action.type);

// Mantener datos para siguientes nodos
return [{json: {
  success: true,
  message: 'Action stored in temporary storage',
  sessionId: sessionId,
  storedAt: new Date().toISOString(),
  actionType: actionData.action.type,
  // Nota: En producción, aquí se guardaría en Redis, MongoDB, etc.
  storageNote: 'Using function node as temporary storage for n8n compatibility'
}}];

// Respuesta para la fase de captura
const response = {
  success: true,
  message: 'Action stored successfully',
  sessionId: $json.sessionId,
  actionType: $json.actionType,
  timestamp: new Date().toISOString()
};

return [{json: response}];

// FASE 2: Preparar generación de tests
const sessionId = $json.sessionId;

if (!sessionId) {
  throw new Error('Session ID is required for test generation');
}

console.log('🚀 Starting test generation for session:', sessionId);

// Pasar el sessionId para recuperar las acciones almacenadas
return [{
  json: {
    sessionId: sessionId,
    requestData: $json,
    startTime: new Date().toISOString()
  }
}];

// SIMULACIÓN DE RECUPERACIÓN DE DATOS (para n8n 1.114.4)
// En una implementación real, esto consultaría una base de datos
const sessionId = $json.sessionId;

console.log(`🔍 [STORAGE] Simulating retrieval for session: ${sessionId}`);

// Simular datos recuperados (en producción vendrían de DB)
// Para propósitos de demo, generar acciones de ejemplo basadas en sessionId
const mockActions = [
  {
    type: 'navigate',
    selector: '',
    url: 'https://example.com',
    title: 'Test Page',
    timestamp: Date.now() - 5000,
    value: ''
  },
  {
    type: 'click',
    selector: '#login-button',
    url: 'https://example.com',
    title: 'Test Page', 
    timestamp: Date.now() - 4000,
    value: ''
  },
  {
    type: 'input',
    selector: '#username',
    url: 'https://example.com',
    title: 'Test Page',
    timestamp: Date.now() - 3000,
    value: 'testuser'
  },
  {
    type: 'input',
    selector: '#password',
    url: 'https://example.com', 
    title: 'Test Page',
    timestamp: Date.now() - 2000,
    value: 'password123'
  },
  {
    type: 'submit',
    selector: '#login-form',
    url: 'https://example.com',
    title: 'Test Page',
    timestamp: Date.now() - 1000,
    value: ''
  }
];

return [{
  json: {
    success: true,
    sessionId: sessionId,
    actionsRetrieved: mockActions.length,
    actions: mockActions,
    note: 'Mock data for n8n compatibility - in production this would query real storage'
  }
}];

// Procesar acciones almacenadas y preparar para IA
const sessionId = $('Prepare Test Generation').item.json.sessionId;
const actionsData = $json.actions || [];

if (!actionsData || actionsData.length === 0) {
  return [{
    json: {
      success: false,
      error: 'No actions found for session',
      sessionId: sessionId
    }
  }];
}

// Validar que tenemos suficientes acciones
if (actionsData.length < 2) {
  return [{
    json: {
      success: false,
      error: 'Insufficient actions for test generation',
      actionsFound: actionsData.length,
      minimumRequired: 2
    }
  }];
}

// Ordenar acciones por timestamp
const sortedActions = actionsData.sort((a, b) => (a.timestamp || 0) - (b.timestamp || 0));

// Enriquecer con metadata
const enrichedData = {
  sessionId: sessionId,
  totalActions: sortedActions.length,
  processedAt: new Date().toISOString(),
  sourceUrl: sortedActions[0]?.url || '',
  pageTitle: sortedActions[0]?.title || '',
  actions: sortedActions.map((action, index) => ({
    ...action,
    actionIndex: index + 1,
    relativeTime: action.timestamp ? action.timestamp - sortedActions[0].timestamp : 0
  }))
};

console.log('✅ Processed', sortedActions.length, 'actions for generation');

return [{json: enrichedData}];

